import java.nio.file.*;import java.io.*;import org.json.*;import android.content.Context;import org.efootballrevival.runtimeprobe.ModPayloadRepair;
public class ColdRepairTest{
 static void check(boolean b,String msg){if(!b)throw new AssertionError(msg);}
 public static void main(String[] args)throws Exception{
  Path assets=Path.of(args[0]),root=Path.of(args[1]);Files.createDirectories(root.resolve("work/tools"));Path save=root.resolve("work/tools/myleague_editor.json");Files.writeString(save,"existing user edits");Context c=new Context(assets.toFile());ModPayloadRepair.ensure(c,root.toFile());JSONArray rows=new JSONObject(Files.readString(assets.resolve("gateway-release/ui6-runtime-manifest.json"))).getJSONArray("files");for(int i=0;i<rows.length();i++)check(Files.size(root.resolve(rows.getJSONObject(i).getString("path")))==rows.getJSONObject(i).getLong("bytes"),"incomplete cold extract");
  Path missing=root.resolve("livedata/pc9298_mobile_and.pak");Files.delete(missing);Path code=root.resolve("work/tools/bridge_73.py");byte[] good=Files.readAllBytes(code),bad=good.clone();bad[0]^=1;Files.write(code,bad);ModPayloadRepair.ensure(c,root.toFile());check(Files.exists(missing),"missing pc9298 not repaired");check(java.util.Arrays.equals(good,Files.readAllBytes(code)),"corrupt code not repaired");check(Files.readString(save).equals("existing user edits"),"user edits overwritten");long mtime=code.toFile().lastModified();ModPayloadRepair.ensure(c,root.toFile());check(mtime==code.toFile().lastModified(),"warm startup rewrites unchanged code");System.out.println("{\"passed\":true,\"critical_payload_files\":"+rows.length()+",\"cold_install\":true,\"missing_pc9298_repaired\":true,\"corrupt_code_repaired\":true,\"mutable_config_preserved\":true,\"warm_start_no_rewrite\":true,\"production_java_helper\":true,\"device_tested\":false}");
 }
}
